import { Controller, Get, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 목록 크기 기본값과 최대값
const DEFAULT_SIZE = 20;
const MAX_SIZE = 200;

interface Area {
  group: string;
  countSql: string;
  listSql: string;
}

// 가정: 권한 범위는 공개범위 전체(ALL)이거나 본인이 쓴 게시물, 보안문서가 아니거나 본인이 기안한 결재문서로 제한한다.
const POST_AREA: Area = {
  group: '업무영역',
  countSql: `SELECT COUNT(*) AS "total" FROM post
    WHERE (title ILIKE :pattern OR content ILIKE :pattern)
    AND (visibility_scope = 'ALL' OR author_id = CAST(:userId AS bigint))`,
  listSql: `SELECT '게시물' AS "area", post_id AS "resourceId", title AS "title", NULL AS "fileName"
    FROM post
    WHERE (title ILIKE :pattern OR content ILIKE :pattern)
    AND (visibility_scope = 'ALL' OR author_id = CAST(:userId AS bigint))
    ORDER BY post_id DESC
    LIMIT :limit OFFSET :offset`,
};

const APPROVAL_AREA: Area = {
  group: '업무영역',
  countSql: `SELECT COUNT(*) AS "total" FROM approval_document
    WHERE (title ILIKE :pattern OR body ILIKE :pattern)
    AND (is_secret = false OR drafter_id = CAST(:userId AS bigint))`,
  listSql: `SELECT '결재문서' AS "area", approval_document_id AS "resourceId", title AS "title", NULL AS "fileName"
    FROM approval_document
    WHERE (title ILIKE :pattern OR body ILIKE :pattern)
    AND (is_secret = false OR drafter_id = CAST(:userId AS bigint))
    ORDER BY approval_document_id DESC
    LIMIT :limit OFFSET :offset`,
};

// 가정: 첨부파일은 파일명(제목)만 검색한다. 내용 검색은 통합검색 엔진 영역이 맡는다.
const ATTACHMENT_AREA: Area = {
  group: '첨부파일',
  countSql: `SELECT COUNT(*) AS "total" FROM attachment
    WHERE file_name ILIKE :pattern`,
  listSql: `SELECT '첨부파일' AS "area", attachment_id AS "resourceId", file_name AS "title", file_name AS "fileName"
    FROM attachment
    WHERE file_name ILIKE :pattern
    ORDER BY attachment_id DESC
    LIMIT :limit OFFSET :offset`,
};

@Controller('api/v1')
export class FnSfr04010Controller {
  @Get('/search-results')
  async searchIntegrated2(@Req() req: Request) {
    const user = currentUser(req);
    user.require('임직원');
    const query = checks.queryOf(req.query);
    const keyword = typeof query['keyword'] === 'string' ? query['keyword'].trim() : '';
    if (!keyword) {
      throw new ApiError(422, 'SEARCH_KEYWORD_REQUIRED', '검색어를 입력해 주세요.');
    }
    const target = typeof query['target'] === 'string' ? query['target'].trim() : '';
    if (target !== '' && target !== '업무영역' && target !== '첨부파일') {
      throw new ApiError(400, 'VALIDATION_FAILED', '검색 대상이 올바르지 않습니다.');
    }
    const page = query['page'] === undefined || query['page'] === '' ? 0 : Number(query['page']);
    if (!Number.isInteger(page) || page < 0) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 번호가 올바르지 않습니다.');
    }
    let size = query['size'] === undefined || query['size'] === '' ? DEFAULT_SIZE : Number(query['size']);
    if (!Number.isInteger(size) || size < 1) {
      throw new ApiError(400, 'VALIDATION_FAILED', '쪽 크기가 올바르지 않습니다.');
    }
    if (size > MAX_SIZE) {
      size = MAX_SIZE;
    }
    const escaped = keyword.replace(/[\\%_]/g, (ch) => '\\' + ch);
    const pattern = '%' + escaped + '%';
    const areas = [POST_AREA, APPROVAL_AREA, ATTACHMENT_AREA].filter(
      (area) => target === '' || area.group === target,
    );

    return transaction(async (db) => {
      const base = { pattern, userId: user.id };
      const counts: number[] = [];
      for (const area of areas) {
        const rows = await db.query(area.countSql, base);
        counts.push(Number(rows[0]['total']));
      }
      const total = counts.reduce((sum, c) => sum + c, 0);
      let skip = page * size;
      let remaining = size;
      const items: unknown[] = [];
      for (let i = 0; i < areas.length; i++) {
        if (remaining <= 0) {
          break;
        }
        const count = counts[i];
        if (skip >= count) {
          skip -= count;
          continue;
        }
        const take = Math.min(remaining, count - skip);
        const rows = await db.query(areas[i].listSql, { ...base, limit: take, offset: skip });
        items.push(...rows);
        remaining -= take;
        skip = 0;
      }
      return { items, page, size, total };
    });
  }
}

