import { useState } from 'react';
import {
  call,
  useData,
  Badge,
  Num,
  Filters,
  Band,
  DataTable,
  Pager,
  Drawer,
  Pairs,
  Tiles,
  Field,
  TextInput,
  Select,
  ErrorText,
} from '../kit';
import type { PageProps, Row, Page } from '../kit';

export default function FnSfr04010Page({ role, notify }: PageProps) {
  const [keyword, setKeyword] = useState('');
  const [target, setTarget] = useState('');
  const [applied, setApplied] = useState({ keyword: '', target: '' });
  const [pageNo, setPageNo] = useState(0);
  const [selected, setSelected] = useState<Row | null>(null);
  const [guide, setGuide] = useState('');
  const size = 20;

  const { data, error, loading } = useData<Page | null>(async () => {
    if (!applied.keyword) {
      return null;
    }
    return call<Page>('GET', '/search-results', role, undefined, {
      keyword: applied.keyword,
      target: applied.target,
      page: pageNo,
      size,
    });
  }, [applied, pageNo, role]);

  function search() {
    if (!keyword.trim()) {
      setGuide('검색어를 입력해 주세요.');
      notify('검색어를 입력해 주세요.');
      return;
    }
    setGuide('');
    setPageNo(0);
    setApplied({ keyword: keyword.trim(), target });
  }

  function reset() {
    setKeyword('');
    setTarget('');
    setGuide('');
    setPageNo(0);
    setApplied({ keyword: '', target: '' });
  }

  const rows = data ? data.items : [];
  const total = data ? data.total : 0;
  const areaCount = (name: string) => rows.filter((r) => r['area'] === name).length;

  return (
    <div className="bento">
      <section className="box span-4">
        <h2>검색 결과</h2>
        <Tiles items={[['전체 건수', <Num value={total} />]]} />
      </section>
      <section className="box span-4">
        <h2>이번 쪽 결재문서</h2>
        <Tiles items={[['건수', <Num value={areaCount('결재문서')} />]]} />
      </section>
      <section className="box span-4">
        <h2>이번 쪽 첨부파일</h2>
        <Tiles items={[['건수', <Num value={areaCount('첨부파일')} />]]} />
      </section>
      <section className="box span-12">
        <h2>통합검색</h2>
        <Filters onSearch={search} onReset={reset}>
          <Field label="검색 키워드" required>
            <TextInput value={keyword} onChange={setKeyword} placeholder="검색어를 입력하세요" />
          </Field>
          <Field label="검색 대상">
            <Select
              value={target}
              onChange={setTarget}
              placeholder="전체"
              options={[
                ['업무영역', '업무영역'],
                ['첨부파일', '첨부파일 제목·내용'],
              ]}
            />
          </Field>
        </Filters>
        {guide ? <ErrorText text={guide} /> : null}
        {error ? <ErrorText text={error} /> : null}
        <Band total={total} />
        <DataTable
          columns={[
            { key: 'area', label: '업무영역 구분', render: (r) => <Badge value={r['area']} /> },
            { key: 'title', label: '결과 제목' },
            { key: 'fileName', label: '파일명' },
          ]}
          rows={rows}
          onRowClick={(r) => setSelected(r)}
          empty={
            !applied.keyword
              ? '검색어를 입력해 주세요.'
              : loading
                ? '검색 중입니다.'
                : '검색 결과가 없습니다.'
          }
        />
        <Pager page={pageNo} size={size} total={total} onPage={setPageNo} />
      </section>
      {selected ? (
        <Drawer title="검색 결과 상세" onClose={() => setSelected(null)}>
          <Pairs
            items={[
              ['업무영역 구분', <Badge value={selected['area']} />],
              ['결과 대상 ID', <Num value={selected['resourceId']} />],
              ['결과 제목', String(selected['title'] ?? '')],
              ['파일명', String(selected['fileName'] ?? '-')],
            ]}
          />
        </Drawer>
      ) : null}
    </div>
  );
}
